<?php
namespace Tests\Feature;use App\Models\Setting;use Illuminate\Database\Schema\Blueprint;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\Schema;use Illuminate\Support\Facades\Storage;use Tests\Support\SecurityTestCase;
final class AdminSystemTest extends SecurityTestCase{protected function setUp():void{parent::setUp();Schema::create('settings',function(Blueprint $t){$t->id();$t->string('setting_key')->unique();$t->string('group_name');$t->text('value')->nullable();$t->string('value_type');$t->boolean('is_encrypted');$t->timestamps();});Storage::fake('local');Storage::fake('public');$this->actingAs($this->user('Administrator'));}public function test_media_manager_accepts_images_and_blocks_other_files():void{$this->post(route('admin.system.filemanager.store'),['file'=>UploadedFile::fake()->create('bad.php',1)])->assertSessionHasErrors('file');$this->post(route('admin.system.filemanager.store'),['file'=>UploadedFile::fake()->image('logo.png')])->assertRedirect();$this->assertCount(1,Storage::disk('public')->files('admin-media'));}public function test_maintenance_and_encrypted_backup():void{$this->put(route('admin.system.maintenance.update'),['enabled'=>'1','message'=>'Soon','image'=>UploadedFile::fake()->image('maintenance.jpg')])->assertRedirect();$this->assertSame('1',Setting::where('setting_key','system.maintenance')->value('value'));$this->assertNotNull(Setting::where('setting_key','system.maintenance_image')->value('value'));$this->post(route('admin.system.backups.store'))->assertRedirect()->assertSessionHasNoErrors();$path=Storage::disk('local')->files('backups')[0];$this->assertStringNotContainsString('users',Storage::disk('local')->get($path));}public function test_system_pages_are_available():void{foreach(['filemanager','update','maintenance','backups'] as $name)$this->get(route('admin.system.'.$name))->assertOk();}}
